SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

-- 1. EXTENSIONS
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. USERS TABLE
CREATE TABLE IF NOT EXISTS users (
    id VARCHAR(100) PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(50) DEFAULT 'siswa',
    name VARCHAR(100),
    nisn VARCHAR(50),
    phone VARCHAR(50),
    school VARCHAR(150),
    level VARCHAR(100),
    grade VARCHAR(255),
    lms_data JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_users_role ON users(role);
CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);

-- 3. LMS COURSES TABLE
CREATE TABLE IF NOT EXISTS lms_courses (
    id VARCHAR(100) PRIMARY KEY,
    category VARCHAR(50),
    level VARCHAR(50),
    subject VARCHAR(100),
    grade VARCHAR(50),
    title VARCHAR(255),
    description TEXT,
    content_json JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_lms_courses_cat_lvl ON lms_courses(category, level);

-- 4. LMS ENROLLMENTS TABLE
CREATE TABLE IF NOT EXISTS lms_enrollments (
    id VARCHAR(100) PRIMARY KEY,
    user_id VARCHAR(100),
    course_id VARCHAR(100),
    progress INTEGER DEFAULT 0,
    completed_modules JSONB DEFAULT '[]'::jsonb,
    enrolled_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    last_accessed TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_id, course_id)
);

-- 5. LMS QUIZ RESULTS TABLE
CREATE TABLE IF NOT EXISTS lms_quiz_results (
    id VARCHAR(100) PRIMARY KEY,
    user_id VARCHAR(100),
    course_id VARCHAR(100),
    module_index VARCHAR(100),
    score NUMERIC(5,2),
    paket INTEGER DEFAULT 1,
    answers_json JSONB,
    submitted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_lms_quiz_results_user ON lms_quiz_results(user_id, submitted_at DESC);

-- 6. LMS QUIZ ATTEMPTS TABLE
CREATE TABLE IF NOT EXISTS lms_quiz_attempts (
    id VARCHAR(100) PRIMARY KEY,
    user_id VARCHAR(100),
    course_id VARCHAR(100),
    module_id VARCHAR(100),
    status VARCHAR(50) DEFAULT 'in_progress',
    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    last_saved_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    elapsed_seconds INTEGER DEFAULT 0,
    answers_json JSONB DEFAULT '{}'::jsonb,
    UNIQUE(user_id, course_id, module_id)
);

-- 7. LMS SCHOOLS TABLE
CREATE TABLE IF NOT EXISTS lms_schools (
    id VARCHAR(100) PRIMARY KEY,
    npsn VARCHAR(50),
    name VARCHAR(255) NOT NULL,
    level VARCHAR(50),
    city VARCHAR(150),
    province VARCHAR(150),
    country VARCHAR(150) DEFAULT 'Indonesia',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 8. ARTICLES TABLE
CREATE TABLE IF NOT EXISTS articles (
    id VARCHAR(100) PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    category VARCHAR(100),
    author VARCHAR(100),
    status VARCHAR(50) DEFAULT 'published',
    content_json JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 9. EVENTS TABLE
CREATE TABLE IF NOT EXISTS events (
    id VARCHAR(100) PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    category VARCHAR(100),
    event_date VARCHAR(50),
    status VARCHAR(50) DEFAULT 'published',
    content_json JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 10. TEACHERS TABLE
CREATE TABLE IF NOT EXISTS teachers (
    id VARCHAR(100) PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    title VARCHAR(150),
    subject VARCHAR(150),
    status VARCHAR(50) DEFAULT 'published',
    content_json JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

