INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-tka-1', 'Panduan Resmi TKA Pusmendik Kemendikdasmen: Struktur Tes, Domain Materi & Bobot Penilaian', 'TKA & Akademik', 'Tim Akademik NLS', 'published', '{"id":"art-tka-1","title":"Panduan Resmi TKA Pusmendik Kemendikdasmen: Struktur Tes, Domain Materi & Bobot Penilaian","slug":"panduan-resmi-tka-pusmendik","category":"TKA & Akademik","categories":["TKA & Akademik","Berita Sekolah & Diknas","Tips Belajar & Prestasi"],"date":"2026-08-25","author":"Tim Akademik NLS","status":"published","coverImage":"/images/blog/cover-osn-matematika.jpg","focusKeyword":"panduan resmi tka pusmendik kemendikdasmen","metaTitle":"Panduan Resmi TKA Pusmendik Kemendikdasmen RI | Next Level Study","metaDescription":"Ulasan komprehensif panduan resmi Tes Kemampuan Akademik (TKA) Pusmendik Kemendikdasmen: domain materi wajib, pilihan saintek/soshum, dan sistem penilaian terstandar.","excerpt":"Ulasan komprehensif panduan resmi Tes Kemampuan Akademik (TKA) Pusmendik Kemendikdasmen: domain materi wajib, pilihan saintek/soshum, dan sistem penilaian terstandar.","content":"<h2>Regulasi Resmi TKA: Standarisasi Capaian Akademik Nasional</h2>\n<p>Pusat Asesmen Pendidikan (Pusmendik) Kemendikdasmen RI secara resmi menyelenggarakan Tes Kemampuan Akademik (TKA) sebagai instrumen evaluasi capaian belajar siswa terstandar nasional. Nilai TKA menjadi tolok ukur obyektif untuk pemetaan mutu sekolah, seleksi lanjutan, dan penguatan portofolio SNBP.</p>\n\n<h3>1. Struktur Mata Pelajaran Wajib</h3>\n<ul>\n  <li><strong>Bahasa Indonesia:</strong> Penalaran teks kompleks, literasi kritis, dan analisis wacana ilmiah.</li>\n  <li><strong>Matematika:</strong> Logika numerik, pemodelan matematis aljabar, kalkulus terapan, dan statistika probabilitas.</li>\n  <li><strong>Bahasa Inggris:</strong> Critical reading comprehension, sintaksis kontekstual, dan inferensi akademik internasional.</li>\n</ul>\n\n<h3>2. Domain Mata Pelajaran Pilihan</h3>\n<p>Siswa dapat memilih mata pelajaran peminatan sesuai rumpun studi yang ditargetkan di perguruan tinggi (Fisika, Kimia, Biologi untuk Saintek; Ekonomi, Sosiologi, Geografi untuk Soshum; serta Bahasa & Vokasi Terapan).</p>\n\n<blockquote>\"TKA bukan sekadar ujian hafalan rumus, melainkan uji penalaran kognitif tingkat tinggi (HOTS) yang mengukur kedalaman konsep.\"</blockquote>","seoScore":95,"isTrashed":0,"createdAt":"2026-08-25T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
