INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-nexgen-1', 'Mengenal Nexgen Academy: Konsep Bimbel Offline Modern Biaya Seikhlasnya di Bekasi', 'Bimbel NexGen', 'Tim Akademik Nexgen', 'published', '{"id":"art-nexgen-1","title":"Mengenal Nexgen Academy: Konsep Bimbel Offline Modern Biaya Seikhlasnya di Bekasi","slug":"mengenal-nexgen-academy-bekasi","category":"Bimbel NexGen","categories":["Bimbel NexGen","Informasi NLS","Tips Belajar & Prestasi"],"date":"2026-08-25","author":"Tim Akademik Nexgen","status":"published","coverImage":"/images/stitch/nexgen-classroom.jpg","focusKeyword":"bimbel nexgen academy bekasi biaya seikhlasnya","metaTitle":"Mengenal Nexgen Academy: Bimbel Offline Modern Bekasi | NLS","metaDescription":"Inovasi bimbel offline modern dengan kelas interaktif AC, smartboard digital, rasio maksimal 10 siswa, dan sistem subsidi pendidikan di Bekasi.","excerpt":"Inovasi bimbel offline modern dengan kelas interaktif AC, smartboard digital, rasio maksimal 10 siswa, dan sistem subsidi pendidikan di Bekasi.","content":"<h2>Revolusi Bimbingan Belajar: Fasilitas Premium, Biaya Berkelanjutan</h2>\n<p><strong>Nexgen Academy</strong> hadir sebagai unit pembelajaran tatap muka (offline) dari Next Level Study Indonesia yang berlokasi di <em>Jalan Pahlawan No. 26, Duren Jaya, Bekasi Timur</em>. Mengusung prinsip kepedulian sosial dalam pendidikan, Nexgen mengedepankan fasilitas modern sekelas bimbel premium namun tetap dapat dijangkau oleh semua kalangan keluarga melalui model kontribusi yang transparan dan bersahabat.</p>\n\n<h3>Keunggulan Utama Belajar di Nexgen Academy:</h3>\n<ul>\n  <li><strong>Ruang Kelas Ber-AC & Full Multimedia:</strong> Suasana belajar sejuk, tenang, dan dilengkapi smart screen proyektor untuk visualisasi materi sains dan matematika.</li>\n  <li><strong>Maksimal 10 Siswa per Kelas:</strong> Memastikan setiap siswa mendapatkan perhatian penuh dari mentor tanpa merasa terabaikan di dalam kelas.</li>\n  <li><strong>Akses Gratis Ekosistem CBT Online NLS:</strong> Siswa offline mendapatkan akun resmi simulasi CBT dan materi video rekaman secara gratis tanpa biaya tambahan.</li>\n  <li><strong>Klinik PR Sepuasnya:</strong> Fasilitas konsultasi tugas rumah sekolah setiap hari bersama tutor pendamping ramah.</li>\n</ul>","seoScore":96,"isTrashed":0,"createdAt":"2026-08-25T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
