INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-snbt-2', 'Bedah Subtes TPS SNBT 2027: Trik Jitu Penalaran Umum & Pengetahuan Kuantitatif', 'SNBT & UTBK', 'Kak Alif (Teknik Elektro UI)', 'published', '{"id":"art-snbt-2","title":"Bedah Subtes TPS SNBT 2027: Trik Jitu Penalaran Umum & Pengetahuan Kuantitatif","slug":"bedah-subtes-tps-snbt","category":"SNBT & UTBK","categories":["SNBT & UTBK","Tips Belajar & Prestasi"],"date":"2026-08-24","author":"Kak Alif (Teknik Elektro UI)","status":"published","coverImage":"/images/blog/cover-snbt-2027.jpg","focusKeyword":"bedah subtes tps snbt trik kuantitatif","metaTitle":"Bedah Subtes TPS SNBT 2027: Trik Penalaran Umum & Kuantitatif | NLS","metaDescription":"Pelajari strategi menjawab soal TPS Penalaran Umum dan Kuantitatif SNBT secara cepat dan akurat untuk memaksimalkan skor IRT Anda.","excerpt":"Pelajari strategi menjawab soal TPS Penalaran Umum dan Kuantitatif SNBT secara cepat dan akurat untuk memaksimalkan skor IRT Anda.","content":"<h2>Kunci Menembus Skor TPS 700+ di UTBK SNBT</h2>\n<p>Tes Potensi Skolastik (TPS) menguji daya nalar kognitif dasar yang menjadi fondasi keberhasilan studi di perguruan tinggi. Penalaran Umum dan Pengetahuan Kuantitatif menyumbang proporsi bobot nilai signifikan dalam sistem pembobotan IRT.</p>\n\n<h3>1. Logika Silogisme & Penalaran Deduktif</h3>\n<p>Kuasai tabel kebenaran implikasi ($p \\rightarrow q$), kontraposisi ($\\sim q \\rightarrow \\sim p$), dan negasi kuantor (Semua vs Beberapa). Jangan terjebak asumsi dunia nyata; selalu berpijak hanya pada premis teks yang diberikan.</p>\n\n<h3>2. Aljabar Cepat & Pola Barisan Angka</h3>\n<p>Identifikasi barisan bertingkat dua, barisan Fibonacci tersembunyi, serta pola operasi aritmetika selang-seling (+, ×, -). Kuasai estimasi nilai pecahan dan persentase tanpa kalkulator manual.</p>\n\n<blockquote>\"TPS menguji seberapa efisien otak Anda memproses pola dan menemukan jalur tercepat menuju solusi logis.\"</blockquote>","seoScore":94,"isTrashed":0,"createdAt":"2026-08-24T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    category = EXCLUDED.category,
    author = EXCLUDED.author,
    status = EXCLUDED.status,
    content_json = EXCLUDED.content_json;
INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-osn-kimia', 'Tips Belajar OSN Kimia SMA: Kuasai Mekanisme Reaksi Organik, Termodinamika & Spektroskopi', 'OSN & Sains', 'Kak Nadia (Tutor Spesialis OSN Kimia)', 'published', '{"id":"art-osn-kimia","title":"Tips Belajar OSN Kimia SMA: Kuasai Mekanisme Reaksi Organik, Termodinamika & Spektroskopi","slug":"tips-belajar-osn-kimia-sma","category":"OSN & Sains","categories":["OSN & Sains","Tips Belajar & Prestasi"],"date":"2026-08-23","author":"Kak Nadia (Tutor Spesialis OSN Kimia)","status":"published","coverImage":"/images/blog/cover-osn-kimia.jpg","focusKeyword":"tips belajar osn kimia sma","metaTitle":"Tips Belajar OSN Kimia SMA: Reaksi Organik & Termodinamika | NLS","metaDescription":"Panduan tips belajar OSN Kimia SMA: strategi mendalam kimia fisik, reaksi organik, stoikiometri analitik, dan analisis spektroskopi NMR bersama NLS.","excerpt":"Panduan tips belajar OSN Kimia SMA: strategi mendalam kimia fisik, reaksi organik, stoikiometri analitik, dan analisis spektroskopi NMR bersama NLS.","content":"<h2>Kunci Menguasai Kimia Kompetisi: Keseimbangan Antara Teori dan Logika Reaksi</h2>\n<p>Olimpiade Sains Nasional Kimia SMA terkenal dengan cakupan materinya yang sangat luas, menjangkau level perkuliahan kimia tingkat dua dan tiga. Untuk meraih medali juara, siswa harus mampu menggabungkan kalkulasi kuantitatif yang presisi pada kimia fisik dengan penalaran kualitatif pada mekanisme reaksi organik dan struktur anorganik.</p>\n\n<h3>1. Fondasi Kimia Fisik: Termodinamika & Kinetika Reaksi</h3>\n<p>Kimia fisik menjadi tulang punggung dari 40% soal olimpiade. Pelajari secara mendalam konsep Entalpi (Delta H), Entropi (Delta S), dan Energi Bebas Gibbs (Delta G). Pahami hubungan kesetimbangan kimia dengan konstanta Van ''t Hoff, elektrokimia persamaan Nernst, serta hukum laju reaksi terintegrasi orde 0, 1, dan 2.</p>\n\n<h3>2. Memahami Logika Mekanisme Reaksi Kimia Organik</h3>\n<p>Alih-alih menghafal ratusan reaksi organik, pahamilah perpindahan elektron melalui notasi panah lengkung (curved arrow mechanism). Kuasai konsep nukleofil-elektrofil, efek induksi, resonansi, sterik, serta mekanisme reaksi penting seperti substitusi nukleofilik (SN1, SN2), eliminasi (E1, E2), adisi elektrofilik alkena, hingga reaksi kondensasi karbonil (Aldol, Claisen).</p>\n\n<h3>3. Analisis Spektroskopi Molekuler Modern</h3>\n<p>Soal OSN tingkat provinsi dan nasional rutin menghadirkan soal penentuan struktur molekul tak dikenal melalui kombinasi data spektrum: 1H-NMR, 13C-NMR, Spektroskopi Inframerah (FT-IR), Spektrometri Massa (MS), dan Spektroskopi UV-Vis. Latihlah kepekaan membaca chemical shift, splitting pattern, dan indeks defisiensi hidrogen (IDH).</p>\n\n<h3>4. Kimia Anorganik & Kompleks Logam Transisi</h3>\n<p>Kuasai konfigurasi elektron ion transisi, geometri molekul VSEPR, teori ikatan valensi, serta Teori Medan Kristal (Crystal Field Theory). Pahami pembagian orbital d, faktor penentu high-spin/low-spin, efek Jahn-Teller, dan deret spektrokimia ligan.</p>\n\n<h3>5. Referensi Belajar Standar Internasional</h3>\n<p>Buku rujukan utama yang wajib dipelajari meliputi <em>Chemistry</em> karya Zumdahl atau Raymond Chang untuk kimia umum, <em>Physical Chemistry</em> karya Peter Atkins, dan <em>Organic Chemistry</em> karya Paula Yurkanis Bruice atau Jonathan Clayden. Bedah soal-soal IChO (International Chemistry Olympiad) untuk melatih daya nalar tingkat tinggi.</p>\n\n<blockquote>\"Di balik setiap tabung reaksi dan perubahan warna larutan, tersimpan hukum-hukum termodinamika dan pergerakan elektron yang menanti untuk dipecahkan secara matematis.\"</blockquote>","seoScore":94,"isTrashed":0,"createdAt":"2026-08-23T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
