    title = EXCLUDED.title,
    category = EXCLUDED.category,
    author = EXCLUDED.author,
    status = EXCLUDED.status,
    content_json = EXCLUDED.content_json;
INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-nexgen-2', 'Mengapa Kelas Maksimal 10 Siswa Lebih Efektif Meningkatkan Prestasi Akademik?', 'Bimbel NexGen', 'Kak Dimas (Koordinator Pengajar)', 'published', '{"id":"art-nexgen-2","title":"Mengapa Kelas Maksimal 10 Siswa Lebih Efektif Meningkatkan Prestasi Akademik?","slug":"efektivitas-kelas-kecil-nexgen","category":"Bimbel NexGen","categories":["Bimbel NexGen","Tips Belajar & Prestasi"],"date":"2026-08-20","author":"Kak Dimas (Koordinator Pengajar)","status":"published","coverImage":"/images/blog/cover-tips-belajar.jpg","focusKeyword":"efektivitas kelas kecil bimbel nexgen","metaTitle":"Efektivitas Kelas Maksimal 10 Siswa di Nexgen Academy | NLS","metaDescription":"Mengapa rasio pengajar dan siswa yang proporsional memungkinkan pendekatan personal, feedback instan, dan peningkatan pemahaman konsep yang terbukti.","excerpt":"Mengapa rasio pengajar dan siswa yang proporsional memungkinkan pendekatan personal, feedback instan, dan peningkatan pemahaman konsep yang terbukti.","content":"<h2>Kelemahan Kelas Masal vs Kekuatan Micro-Classroom</h2>\n<p>Dalam kelas bimbel konvensional yang menampung 25-35 murid, siswa yang pasif atau memiliki pemahaman dasar yang lambat sering kali tertinggal dan enggan bertanya. Nexgen Academy menerapkan batasan ketat: <strong>maksimal 10 siswa per rombongan belajar</strong>.</p>\n\n<h3>Manfaat Nyata Sistem Kelas Kecil:</h3>\n<ol>\n  <li><strong>Deteksi Cepat Titik Kesulitan:</strong> Mentor dapat segera mengetahui baris langkah hitungan mana yang belum dipahami siswa.</li>\n  <li><strong>Diskusi Dua Arah yang Aktif:</strong> Setiap anak didorong untuk mengutarakan argumen logika matematikanya secara percaya diri.</li>\n  <li><strong>Kurikulum yang Menyesuaikan Ritme Siswa:</strong> Pembahasan dapat diperdalam pada topik yang dirasa paling menantang oleh anggota kelas.</li>\n</ol>","seoScore":94,"isTrashed":0,"createdAt":"2026-08-20T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    category = EXCLUDED.category,
    author = EXCLUDED.author,
    status = EXCLUDED.status,
    content_json = EXCLUDED.content_json;
INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-osn-kebumian', 'Tips Belajar OSN Kebumian SMA: Integrasi Geologi, Meteorologi, Oseanografi & Sistem Bumi Global', 'OSN & Sains', 'Kak Fajar (Medalis OSN Kebumian)', 'published', '{"id":"art-osn-kebumian","title":"Tips Belajar OSN Kebumian SMA: Integrasi Geologi, Meteorologi, Oseanografi & Sistem Bumi Global","slug":"tips-belajar-osn-kebumian-sma","category":"OSN & Sains","categories":["OSN & Sains","Tips Belajar & Prestasi"],"date":"2026-08-19","author":"Kak Fajar (Medalis OSN Kebumian)","status":"published","coverImage":"/images/blog/cover-osn-kebumian.jpg","focusKeyword":"tips belajar osn kebumian sma","metaTitle":"Tips Belajar OSN Kebumian SMA: Geologi & Sistem Atmosfer | NLS","metaDescription":"Pelajari tips belajar OSN Kebumian SMA: identifikasi mineral batuan, dinamika atmosfer cuaca, oseanografi fisik, dan persiapan praktikum lapangan.","excerpt":"Pelajari tips belajar OSN Kebumian SMA: identifikasi mineral batuan, dinamika atmosfer cuaca, oseanografi fisik, dan persiapan praktikum lapangan.","content":"<h2>Memahami Bumi Sebagai Satu Kesatuan Sistem Dinamis Terpadu</h2>\n<p>Ilmu Kebumian (Earth Science) adalah studi holistik yang meneliti interaksi kompleks antara Geosfer (litosfer & mantel), Atmosfer, Hidrosfer, dan pengaruh Astronomi Tata Surya terhadap dinamika planet Bumi. Dalam OSN Kebumian SMA, peserta diuji kemampuannya mengintegrasikan hukum fisika dan kimia untuk menjelaskan fenomena alam global.</p>\n\n<h3>1. Geologi: Petrologi, Mineralogi, dan Tektonik Lempeng</h3>\n<p>Kuasai pembentukan batuan beku, sedimen, dan metamorf melalui siklus batuan. Pelajari identifikasi sifat fisik mineral (kekerasan skala Mohs, kilap, gores, belahan), struktur geologi (sesar, lipatan, ketidakselarasan), stratigrafi hukum Steno, serta mekanisme pergerakan lempeng konvergen, divergen, dan transform.</p>\n\n<h3>2. Meteorologi: Dinamika Cuaca dan Sirkulasi Atmosfer</h3>\n<p>Pahami struktur lapisan atmosfer, radiasi matahari, kelembapan udara (spesifik & relatif), proses pembentukan awan, gaya Coriolis, angin geostrofik, serta fenomena iklim global seperti El Nino, La Nina, Dipole Mode, dan sirkulasi monsun di kepulauan Indonesia.</p>\n\n<h3>3. Oseanografi: Fisika dan Kimia Samudra</h3>\n<p>Pelajari profil suhu, salinitas, dan densitas kolom air laut (termoklin, haloklin, piknoklin). Kuasai mekanisme arus laut permukaan akibat angin (Spiral Ekman), sirkulasi termohalin laut dalam (Great Ocean Conveyor Belt), gelombang laut, dan dinamika pasang surut gravitasi Bulan-Matahari.</p>\n\n<h3>4. Astronomi Planetologi & Geofisika</h3>\n<p>Pahami struktur internal Bumi melalui rambatan gelombang seismik P dan S, medan magnet geomagnetik, proses diferensiasi planet kebumian (Terrestrial Planets), asteroid, komet, serta dampak tumbukan meteorik terhadap kepunahan massal dalam skala waktu geologi.</p>\n\n<h3>5. Persiapan Ujian Praktikum Identifikasi Lapangan</h3>\n<p>Di tahap nasional (dan seleksi IESO), peserta akan menghadapi tes praktikum identifikasi 20+ sampel mineral dan batuan asli, interpretasi peta topografi kontur & peta geologi regional, analisis peta sinoptik cuaca, serta pengukuran lapangan menggunakan kompas geologi Brunton.</p>\n\n<blockquote>\"Membaca lapisan batuan dan dinamika samudra adalah cara terbaik mendengarkan kisah sejarah perjalanan planet Bumi selama 4,5 miliar tahun terakhir.\"</blockquote>","seoScore":93,"isTrashed":0,"createdAt":"2026-08-19T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
