    title = EXCLUDED.title,
    category = EXCLUDED.category,
    author = EXCLUDED.author,
    status = EXCLUDED.status,
    content_json = EXCLUDED.content_json;
INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-snbt-3', 'Kupas Tuntas Literasi Bahasa Indonesia & Bahasa Inggris UTBK SNBT: Membaca Kritis & Analisis Argumen', 'SNBT & UTBK', 'Kak Zahra (Sastra Inggris UGM)', 'published', '{"id":"art-snbt-3","title":"Kupas Tuntas Literasi Bahasa Indonesia & Bahasa Inggris UTBK SNBT: Membaca Kritis & Analisis Argumen","slug":"strategi-literasi-utbk-snbt","category":"SNBT & UTBK","categories":["SNBT & UTBK","Tips Belajar & Prestasi"],"date":"2026-08-19","author":"Kak Zahra (Sastra Inggris UGM)","status":"published","coverImage":"/images/blog/cover-osn-geografi.jpg","focusKeyword":"literasi bahasa indonesia inggris utbk snbt","metaTitle":"Strategi Menguasai Literasi Bahasa Indonesia & Inggris SNBT | NLS","metaDescription":"Metode membaca cepat skimming-scanning, inferensi implisit, dan analisis teks argumentatif panjang pada subtes literasi SNBT.","excerpt":"Metode membaca cepat skimming-scanning, inferensi implisit, dan analisis teks argumentatif panjang pada subtes literasi SNBT.","content":"<h2>Tantangan Waktu pada Teks Panjang Subtes Literasi</h2>\n<p>Subtes Literasi dalam Bahasa Indonesia dan Bahasa Inggris menyajikan teks wacana multi-paragraf yang menuntut pemahaman kritis dalam durasi terbatas per butir soal.</p>\n\n<h3>Metode 3 Langkah ''Question-First Reading''</h3>\n<ol>\n  <li><strong>Baca Pertanyaan Terlebih Dahulu:</strong> Tandai kata kunci pada opsi jawaban sebelum membaca teks.</li>\n  <li><strong>Skimming Paragraf Pertama & Terakhir:</strong> Identifikasi tesis utama dan konklusi penulis dalam 20 detik.</li>\n  <li><strong>Scanning Kata Kunci Spesifik:</strong> Cari kalimat target yang memuat informasi pendukung secara presisi.</li>\n</ol>","seoScore":93,"isTrashed":0,"createdAt":"2026-08-19T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
