INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-tka-3', 'Manajemen Waktu & Strategi Pengerjaan Saat Simulasi TKA Berstandar Nasional', 'TKA & Akademik', 'Kak Sarah (Psikologi UI)', 'published', '{"id":"art-tka-3","title":"Manajemen Waktu & Strategi Pengerjaan Saat Simulasi TKA Berstandar Nasional","slug":"manajemen-waktu-simulasi-tka","category":"TKA & Akademik","categories":["TKA & Akademik","Tips Belajar & Prestasi"],"date":"2026-08-18","author":"Kak Sarah (Psikologi UI)","status":"published","coverImage":"/images/blog/cover-osn-biologi.jpg","focusKeyword":"manajemen waktu simulasi tka","metaTitle":"Manajemen Waktu Saat Simulasi Try Out TKA Nasional | NLS","metaDescription":"Panduan manajemen alokasi waktu per butir soal, teknik eliminasi opsi cerdas, dan mitigasi stres saat menghadapi simulasi TKA nasional.","excerpt":"Panduan manajemen alokasi waktu per butir soal, teknik eliminasi opsi cerdas, dan mitigasi stres saat menghadapi simulasi TKA nasional.","content":"<h2>Strategi Alokasi Waktu: Kunci Lolos Ambang Batas Tertinggi</h2>\n<p>Banyak siswa dengan kemampuan akademik mumpuni gagal memaksimalkan skor TKA hanya karena kehabisan waktu di 10 soal terakhir. Kunci keberhasilan terletak pada strategi <em>Time Management</em> yang disiplin.</p>\n\n<h3>Sistem 3 Ronde Pengerjaan Soal</h3>\n<ol>\n  <li><strong>Ronde 1 (40% Waktu):</strong> Kerjakan soal-soal langsung paham dengan tingkat kepastian jawaban > 90%. Lewati segera soal dengan bacaan > 3 paragraf.</li>\n  <li><strong>Ronde 2 (45% Waktu):</strong> Selesaikan soal tipe analisis menengah dan hitungan yang membutuhkan 2-3 langkah pengerjaan.</li>\n  <li><strong>Ronde 3 (15% Waktu Terakhir):</strong> Evaluasi soal bertanda ragu-ragu dan soal menantang dengan teknik eliminasi opsi rasional.</li>\n</ol>","seoScore":92,"isTrashed":0,"createdAt":"2026-08-18T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    category = EXCLUDED.category,
    author = EXCLUDED.author,
    status = EXCLUDED.status,
    content_json = EXCLUDED.content_json;
INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-osn-geografi', 'Tips Belajar OSN Geografi SMA: Analisis Spasial Keruangan, SIG, Geomorfologi & Studi Lapangan Mandiri', 'OSN & Sains', 'Kak Rian (Medalis OSN Geografi)', 'published', '{"id":"art-osn-geografi","title":"Tips Belajar OSN Geografi SMA: Analisis Spasial Keruangan, SIG, Geomorfologi & Studi Lapangan Mandiri","slug":"tips-belajar-osn-geografi-sma","category":"OSN & Sains","categories":["OSN & Sains","Tips Belajar & Prestasi"],"date":"2026-08-17","author":"Kak Rian (Medalis OSN Geografi)","status":"published","coverImage":"/images/blog/cover-osn-geografi.jpg","focusKeyword":"tips belajar osn geografi sma","metaTitle":"Tips Belajar OSN Geografi SMA: Analisis Spasial & SIG | NLS","metaDescription":"Panduan tips belajar OSN Geografi SMA: interpretasi citra satelit, analisis SIG keruangan, geomorfologi wilayah, dan teknik esai argumentatif iGeo.","excerpt":"Panduan tips belajar OSN Geografi SMA: interpretasi citra satelit, analisis SIG keruangan, geomorfologi wilayah, dan teknik esai argumentatif iGeo.","content":"<h2>Geografi Modern: Sintesis Sains Fisik, Sosial Keruangan, dan Teknologi Geospasial</h2>\n<p>OSN Geografi SMA merupakan kompetisi multidisipliner yang menuntut pemahaman mendalam mengenai bentang alam bumi, interaksi manusia dengan lingkungan, tata ruang wilayah perkotaan, serta pemanfaatan teknologi mutakhir Sistem Informasi Geografis (SIG) dan Penginderaan Jauh.</p>\n\n<h3>1. Geografi Fisik: Geomorfologi, Hidrologi, dan Biogeografi</h3>\n<p>Pahami proses endogen (tektonisme, vulkanisme, seisme) dan proses eksogen (pelapukan, erosi, sedimentasi, mass wasting) yang membentuk bentang alam karst, glasial, aeolian, dan fluvial. Kuasai siklus hidrologi DAS (Daerah Aliran Sungai), debit air permukaan, serta sebaran bioma flora-fauna dunia berdasarkan garis Wallace-Weber.</p>\n\n<h3>2. Geografi Manusia, Urbanisasi, dan Tata Ruang Kota</h3>\n<p>Pelajari dinamika kependudukan (natalitas, mortalitas, migrasi, bonus demografi), model struktur ruang kota (Konsentris Burgess, Sektoral Hoyt, Inti Berganda Harris-Ullman), interaksi desa-kota model gravitasi Reilly, serta tantangan pembangunan berkelanjutan (SDGs).</p>\n\n<h3>3. Penginderaan Jauh & Sistem Informasi Geografis (SIG)</h3>\n<p>Kuasai prinsip interpretasi citra satelit dan foto udara melalui 8 unsur interpretasi (rona, warna, bentuk, ukuran, tekstur, pola, bayangan, situs, asosiasi). Pahami komponen data spasial vektor-raster, analisis tumpang-susun peta (overlay buffer), dan sistem proyeksi peta (Mercator, UTM).</p>\n\n<h3>4. Mitigasi Kebencanaan dan Manajemen Lingkungan Hidup</h3>\n<p>Sebagai negara di kawasan Cincin Api Pasifik (Ring of Fire), peserta OSN Geografi Indonesia wajib memahami siklus manajemen bencana: pra-bencana (mitigasi struktural/non-struktural & peringatan dini), tanggap darurat, serta pasca-bencana (rehabilitasi & rekonstruksi).</p>\n\n<h3>5. Keterampilan Ujian Esai Terbuka & Fieldwork Test (iGeo Standard)</h3>\n<p>Format ujian OSN Geografi nasional mengadopsi standar International Geography Olympiad (iGeo) yang terdiri dari 3 ronde: <em>Written Response Test (WRT)</em> berupa esai analisis analitis, <em>Multimedia Test (MMT)</em> dengan durasi singkat berbasis visual, serta <em>Fieldwork Exercise</em> observasi lapangan dan pembuatan peta tata guna lahan rekomendasi.</p>\n\n<blockquote>\"Melalui kacamata geografi, setiap jengkal permukaan bumi adalah kanvas interaksi dinamis antara kekuatan alam dan peradaban manusia.\"</blockquote>","seoScore":93,"isTrashed":0,"createdAt":"2026-08-17T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    category = EXCLUDED.category,
