INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-nexgen-3', 'Fasilitas Klinik PR & Pendampingan Tugas: Solusi Bebas Stres Belajar Harian Siswa', 'Bimbel NexGen', 'Kak Rina (Mentor Sains Nexgen)', 'published', '{"id":"art-nexgen-3","title":"Fasilitas Klinik PR & Pendampingan Tugas: Solusi Bebas Stres Belajar Harian Siswa","slug":"fasilitas-klinik-pr-pendampingan-nexgen","category":"Bimbel NexGen","categories":["Bimbel NexGen","Tips Belajar & Prestasi","Informasi NLS"],"date":"2026-08-16","author":"Kak Rina (Mentor Sains Nexgen)","status":"published","coverImage":"/images/blog/cover-osn-fisika.jpg","focusKeyword":"klinik pr bimbel nexgen academy","metaTitle":"Klinik PR & Pendampingan Tugas di Nexgen Academy | NLS","metaDescription":"Layanan bimbingan klinik PR gratis bagi siswa untuk mengurai tugas sekolah yang sulit bersama mentor ramah sebelum ujian sekolah.","excerpt":"Layanan bimbingan klinik PR gratis bagi siswa untuk mengurai tugas sekolah yang sulit bersama mentor ramah sebelum ujian sekolah.","content":"<h2>Jangan Biarkan Tugas Sekolah Menumpuk Menjadi Beban Pikiran</h2>\n<p>Banyak siswa merasa tertekan ketika menghadapi PR Matematika, Fisika, atau Kimia yang rumit tanpa ada tempat bertanya di rumah. Di Nexgen Academy, kami menyediakan <strong>Klinik PR Harian</strong> di luar jam sesi kelas reguler.</p>\n\n<h3>Bagaimana Klinik PR Bekerja?</h3>\n<ul>\n  <li>Siswa dapat datang lebih awal atau menetap setelah sesi kelas untuk membawa tugas sekolah yang belum tuntas.</li>\n  <li>Mentor tidak sekadar memberikan jawaban, melainkan membedah konsep dasar hingga siswa mampu menyelesaikan soal serupa secara mandiri.</li>\n  <li>Tersedia area belajar mandiri yang tenang dan koneksi internet cepat untuk riset materi tugas sekolah.</li>\n</ul>","seoScore":93,"isTrashed":0,"createdAt":"2026-08-16T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    category = EXCLUDED.category,
    author = EXCLUDED.author,
    status = EXCLUDED.status,
    content_json = EXCLUDED.content_json;
INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-tka-4', 'Kupas Tuntas Literasi Bahasa Indonesia & Bahasa Inggris pada Standar Baru TKA', 'TKA & Akademik', 'Kak Nabila (Linguistik UGM)', 'published', '{"id":"art-tka-4","title":"Kupas Tuntas Literasi Bahasa Indonesia & Bahasa Inggris pada Standar Baru TKA","slug":"memahami-struktur-literasi-bahasa-tka","category":"TKA & Akademik","categories":["TKA & Akademik","Tips Belajar & Prestasi"],"date":"2026-08-15","author":"Kak Nabila (Linguistik UGM)","status":"published","coverImage":"/images/blog/cover-osn-kimia.jpg","focusKeyword":"literasi bahasa indonesia inggris tka","metaTitle":"Kupas Tuntas Struktur Literasi Bahasa Indonesia & Inggris TKA | NLS","metaDescription":"Memahami model soal literasi kritis, analisis teks argumentatif, inferensi konteks, dan struktur bacaan pada kurikulum baru TKA Pusmendik.","excerpt":"Memahami model soal literasi kritis, analisis teks argumentatif, inferensi konteks, dan struktur bacaan pada kurikulum baru TKA Pusmendik.","content":"<h2>Literasi Tingkat Lanjut: Bukan Sekadar Membaca Paragraf</h2>\n<p>Model asesmen TKA menuntut kemampuan sintesis lintas teks, evaluasi bias penulis, dan pemahaman argumen implisit. Teks yang disajikan mencakup artikel jurnal ilmiah populer, studi kasus sosio-humaniora, dan esai analitis kontemporer.</p>\n\n<h3>Keterampilan Kunci yang Diuji:</h3>\n<ul>\n  <li><strong>Menentukan Ide Pokok & Argumen Utama:</strong> Membedakan gagasan pokok pendukung vs premis inti kalimat.</li>\n  <li><strong>Analisis Hubungan Sebab-Akibat:</strong> Menilai validitas inferensi logis antar paragraf.</li>\n  <li><strong>Kontekstualisasi Kosakata Akademik:</strong> Memahami makna leksikal kata serapan dalam konteks kalimat kompleks.</li>\n</ul>","seoScore":93,"isTrashed":0,"createdAt":"2026-08-15T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
