INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-snbt-4', 'Strategi Memilih Program Studi & Analisis Keketatan PTN pada SNBT 2027', 'SNBT & UTBK', 'Kak Bima (Statistika UGM)', 'published', '{"id":"art-snbt-4","title":"Strategi Memilih Program Studi & Analisis Keketatan PTN pada SNBT 2027","slug":"strategi-memilih-prodi-snbt","category":"SNBT & UTBK","categories":["SNBT & UTBK","Tips Belajar & Prestasi","Informasi NLS"],"date":"2026-08-14","author":"Kak Bima (Statistika UGM)","status":"published","coverImage":"/images/blog/cover-jurusan-kuliah.jpg","focusKeyword":"strategi memilih prodi snbt ptn favorit","metaTitle":"Strategi Memilih Prodi & Analisis Rasio Keketatan SNBT | NLS","metaDescription":"Panduan realistis memilih pilihan 1, 2, 3, dan 4 pada SNBT berdasarkan simulasi skor IRT try out dan kuota daya tampung PTN.","excerpt":"Panduan realistis memilih pilihan 1, 2, 3, dan 4 pada SNBT berdasarkan simulasi skor IRT try out dan kuota daya tampung PTN.","content":"<h2>Rasionalisasi Pilihan: Hindari Strategi ''Berjudi'' Tanpa Data</h2>\n<p>Dengan sistem 4 pilihan pada SNBT terbaru, kombinasi program Sarjana dan Vokasi memberikan peluang kelolosan yang jauh lebih terbuka bila dirancang dengan rasionalisasi data kuota daya tampung dan rasio peminat historis.</p>\n\n<h3>Matriks Portofolio 4 Pilihan:</h3>\n<ul>\n  <li><strong>Pilihan 1 (Dream Major):</strong> Jurusan impian dengan passing grade tertinggi sesuai batas atas capaian tryout.</li>\n  <li><strong>Pilihan 2 (Target Major):</strong> Jurusan realistis dengan peluang kelolosan > 75% berdasarkan rata-rata skor stabil.</li>\n  <li><strong>Pilihan 3 & 4 (Safety Major / Vokasi Terapan):</strong> Program Sarjana Terapan (D4/D3) unggulan dengan prospek kerja industri tinggi.</li>\n</ul>","seoScore":95,"isTrashed":0,"createdAt":"2026-08-14T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    category = EXCLUDED.category,
    author = EXCLUDED.author,
    status = EXCLUDED.status,
    content_json = EXCLUDED.content_json;
INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-3', 'Tips Memilih Jurusan Kuliah Sesuai Minat, Bakat, dan Prospek Karier Masa Depan', 'Tips Belajar & Prestasi', 'Kak Bima (Statistika UGM)', 'published', '{"id":"art-3","title":"Tips Memilih Jurusan Kuliah Sesuai Minat, Bakat, dan Prospek Karier Masa Depan","slug":"tips-memilih-jurusan-kuliah-masa-depan","category":"Tips Belajar & Prestasi","categories":["Tips Belajar & Prestasi","Informasi NLS"],"date":"2026-08-10","author":"Kak Bima (Statistika UGM)","status":"published","coverImage":"/images/blog/cover-jurusan-kuliah.jpg","focusKeyword":"tips memilih jurusan kuliah","metaTitle":"Tips Memilih Jurusan Kuliah Sesuai Minat & Prospek Karier | NLS","metaDescription":"Panduan komprehensif cara memilih jurusan kuliah yang tepat di PTN favorit sesuai minat, bakat, potensi akademik, dan prospek karier masa depan.","excerpt":"Panduan komprehensif cara memilih jurusan kuliah yang tepat di PTN favorit sesuai minat, bakat, potensi akademik, dan prospek karier masa depan.","content":"<h2>Salah Jurusan: Masalah Klasik yang Harus Dihindari</h2>\n<p>Riset menunjukkan lebih dari 80% mahasiswa di Indonesia merasa salah memilih program studi. Memilih jurusan kuliah adalah keputusan strategis yang akan membentuk lintasan karier dan pengembangan profesional Anda di masa depan.</p>\n\n<h3>Formula 3A dalam Memilih Jurusan</h3>\n<ol>\n  <li><strong>Aptitude (Bakat & Kemampuan Akademik):</strong> Ukur performa nilai rapor dan skor try out pada mata pelajaran kunci.</li>\n  <li><strong>Affinity (Minat & Gairah Belajar):</strong> Bidang apa yang membuat Anda bersemangat untuk belajar secara mandiri tanpa paksaan?</li>\n  <li><strong>Application (Peluang Kerja & Tren Industri):</strong> Analisis kebutuhan industri 5-10 tahun ke depan, seperti Data Science, Artificial Intelligence, Green Energy, dan Bioteknologi.</li>\n</ol>","seoScore":90,"isTrashed":0,"createdAt":"2026-08-10T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    category = EXCLUDED.category,
    author = EXCLUDED.author,
    status = EXCLUDED.status,
    content_json = EXCLUDED.content_json;
INSERT INTO articles (id, title, category, author, status, content_json)
VALUES ('art-nexgen-4', 'Integrasi Smartboard Digital & Platform CBT NLS pada Pembelajaran Offline Nexgen', 'Bimbel NexGen', 'Tim EduTech NLS', 'published', '{"id":"art-nexgen-4","title":"Integrasi Smartboard Digital & Platform CBT NLS pada Pembelajaran Offline Nexgen","slug":"inovasi-teknologi-belajar-nexgen","category":"Bimbel NexGen","categories":["Bimbel NexGen","Informasi NLS","Tips Belajar & Prestasi"],"date":"2026-08-10","author":"Tim EduTech NLS","status":"published","coverImage":"/images/blog/cover-osn-informatika.jpg","focusKeyword":"teknologi belajar smartboard bimbel nexgen","metaTitle":"Inovasi Smartboard Digital & CBT di Nexgen Academy | NLS","metaDescription":"Bagaimana perpaduan fasilitas ruang kelas modern, smart screen, dan simulasi CBT online mempercepat pemahaman materi sains dan numerasi.","excerpt":"Bagaimana perpaduan fasilitas ruang kelas modern, smart screen, dan simulasi CBT online mempercepat pemahaman materi sains dan numerasi.","content":"<h2>Sinergi Pembelajaran Tatap Muka dengan Kecanggihan Digital</h2>\n<p>Belajar offline di Nexgen Academy bukan berarti menggunakan cara lama yang membosankan. Kami mengintegrasikan papan tulis digital interaktif (*Smartboard*) dengan ekosistem perangkat lunak CBT Next Level Study.</p>\n\n<h3>Fitur Pembelajaran Hybrid di Kelas:</h3>\n<ul>\n  <li><strong>Visualisasi Geometri 3D & Simulasi Sains:</strong> Grafik fungsi kalkulus, medan magnet, dan reaksi kimia dapat dimanipulasi secara visual di layar kelas.</li>\n  <li><strong>Catatan Mentor Terdistribusi Otomatis:</strong> Tulisan dan rangkuman rumus di papan tulis langsung tersimpan dalam format PDF dan dikirimkan ke grup belajar siswa.</li>\n  <li><strong>Latihan Try Out Mandiri di Rumah:</strong> Evaluasi hasil belajar di kelas dapat diuji secara langsung melalui simulasi berkala berbasis IRT di website CBT NLS.</li>\n</ul>","seoScore":95,"isTrashed":0,"createdAt":"2026-08-10T00:00:00.000Z","updatedAt":"2026-08-29T17:49:09.403Z"}'::jsonb)
